import{C as s,b as x,c as u}from"./dom-6kYVTdCz.js";import{b as N,c as a,t}from"./header-Bo-VLoH0.js";const F={"se.character.awareness.why":"contact runs ahead of self-report: it acts, then finds out it acted","se.character.control.why":"follows the field's action more readily than an inner agenda","se.character.endurance.why":"contact pays back in the moment — a live field can be ridden for hours","se.character.precision.why":"full resolution at zero lag, for exactly as long as the contact lasts","se.character.speed.why":"locks within a single frame — the fastest event in the psyche","se.energy.recovery.auxiliary":"Quick, once the tools are down and the scene is closed.","se.energy.recovery.dominant":"Refills during use — full contact is cheaper than resting badly.","se.energy.recovery.inferior":"The hangover shelf: ~30 min where the overstimulation lingers and every channel runs dim.","se.energy.recovery.shadow":"Incomplete — voltage spent here does not fully return today.","se.energy.recovery.tertiary":"Needs the plan put away first; presence bought on a schedule recovers on one.","se.feeder.fe":{figure:"Dwell time collapses to zero; the reticle chases applause.",mechanism:"The ESTP loop, with Ti cut out: Fe — extraverted feeling — supplies targets, but only social ones — the laugh, the reaction, the room's next dare — and every hit is spent immediately on setting up the next. Nothing is examined, nothing savoured; the show simply escalates. The missing piece is the auxiliary's quiet question: is this actually a good idea?",pair:"the ESTP Se–Fe loop",provenance:"community",warn:"Loop coupling: dominant and tertiary, both extraverted — the auxiliary's inner check is cut out."},"se.feeder.fi":{figure:"The right targets glow, and the reticle lingers.",mechanism:"Fi — introverted feeling — hands the eye a felt criterion: what is beautiful, what is honest, what is worth savouring. The world sorts itself by significance, and a lock is held long past its tactical use, because the point was never tactics. The performer's and the aesthete's gaze: full presence, aimed at what the heart already chose.",pair:"the ISFP · ESFP coupling",provenance:"myers"},"se.feeder.ni":{figure:"Locks abort halfway, again and again.",mechanism:"Ni — introverted intuition — keeps interrupting looking with meaning: every lock aborts midway because the target has already become a symbol of something else. The eye retargets constantly and finishes nothing; the world is entirely present and never actually seen. These two share an axis for a reason — real stacks put a judge between them.",pair:"perception feeding perception",provenance:"myers",warn:"Unstable coupling: perception feeding perception, with nothing judging either."},"se.feeder.te":{figure:"The reticle sprints a checklist that refills itself.",mechanism:"The ESFP loop, with Fi cut out: Te — extraverted thinking — turns the field into a task list — visible, finishable, immediately replaced — and the eye rides from errand to errand at full speed. Motion becomes its own proof of progress; whether any of it matters to the person doing it is exactly the question the loop bypasses.",pair:"the ESFP Se–Te loop",provenance:"community",warn:"Loop coupling: dominant and tertiary, both extraverted — the auxiliary's inner check is cut out."},"se.feeder.ti":{figure:"Measurement tags bloom on whatever the reticle locks.",mechanism:"Ti — introverted thinking — hands the eye a spec: tolerances, mechanisms, the one measurement that settles it. Salience reorganises around what matters — fewer targets, locked harder, read to the millimetre. The troubleshooter's gaze: the machine in front of you, interrogated part by part, and the diagnosis checked against the thing itself.",pair:"the ISTP · ESTP coupling",provenance:"myers"},"se.fieldNotes.mirror":{figure:"One is water that looks; the other is water that keeps.",mechanismHtml:"Same element, opposite attitude — and the difference is what happens to the moment. <strong>Se</strong> rides it: full resolution, zero lag, nothing kept — the world as a place to act. <strong>Si</strong> banks it: metered intake, compared against every layer it has ever laid down — the world as a place to recognise. Se trades the record for the moment; Si trades the moment for a record no moment can take away.",provenance:"jung"},"se.fieldNotes.vignette.court":{figure:"Reticle, lock, launch — one frame.",kind:"field sighting",mechanism:"Mid-game, an ESTP sees the defender's weight shift a half-second before the lane opens, and is already moving. Asked afterwards how they knew, they say they saw it — which is the whole answer. There was no inference to report; the perception and the move were one event, and the interview about it is the first part that costs effort.",provenance:"community",title:"The Court"},"se.fieldNotes.vignette.fiveYearPlan":{figure:"The sharpest instrument in the building, with nothing to grip.",kind:"the wrong instrument",mechanism:"Hand Se the strategy offsite — the market in 2031, the succession question, the bet whose payoff no one in the room will see this year — and contact has no surface, because the future does not have one yet. A strong Se-dominant does not fake the long view; they partner with someone who has it, and take the part of the plan that touches ground this quarter — which, done at their resolution, is a contribution no planner can match.",provenance:"community",title:"The Five-Year Plan"},"se.fieldNotes.vignette.grip":{figure:"The iris cedes to a dark funnel.",kind:"the grip",mechanism:"An ESFP past the end of their reserves stops perceiving and starts foreboding — sudden grim certainties about what it all means and where it is heading, delivered with none of dominant intuition's craft. Not a personality change: a low-capacity seat taking a dominant-sized flood.",provenance:"quenk",title:"The Grip"},"se.fieldNotes.vignette.loop":{figure:"Every stunt buys the next; the gate never closes.",kind:"the loop",mechanism:"An ESTP under pressure pairs dominant Se with tertiary Fe: the room's reaction becomes the only instrument, and every stunt buys the next one. Ti's quiet question — is this actually a good idea? — is the function the loop exists to avoid. From inside it feels like being on; from outside it looks like escalation.",provenance:"community",title:"The Loop"},"se.fieldNotes.vignette.mistakenForNe":{figure:"This wave, not a better idea of one.",kind:"the misread",mechanism:'Both read as "spontaneous," and the two get swapped in both directions. The tell is the object of the appetite. Se wants the actual thing at actual intensity — this wave, this crowd, this engine — and finds talking about hypothetical waves a poor substitute for water. Ne wants the possibility and will trade the concert in front of it for a better idea of a concert. Watch where the attention lands when both are in one room: one on the stage, one on what the venue could become.',provenance:"community",title:"Mistaken for Ne"},"se.fieldNotes.vignette.reckless":{figure:"Frame-rate data the guardrail never sees.",kind:"the accusation",mechanism:"The verdict is usually delivered by someone whose risk estimate ran on precedent rather than on the scene. What the accuser cannot see is the resolution: the rider read this surface, this camber, this grip, at frame rate, and priced the move against data they will never have from the guardrail. Dominant Se's error rate is often lowest exactly where the stakes are highest — that is what full contact buys. The honest caveat sits lower in the stack: the same move from the tertiary or inferior seat runs on a fraction of the resolution and all of the appetite.",provenance:"community",title:'"Reckless"'},"se.fieldNotes.vignette.scheduledBody":{figure:"Full aperture, by appointment.",kind:"as a tertiary",mechanism:"Tertiary Se in an ENTJ or ENFJ: presence, purchased in blocks. The motorcycle weekend, the boxing class at six, the kitchen renovated to restaurant grade — real contact with the physical world, genuinely relished, and booked into the calendar by the long-range machinery that runs the rest of the week. The tell is the transition: fully in the body on Saturday, and by Monday the senses have gone back to executive summary.",provenance:"grant",title:"The Scheduled Body"},"se.hero.heading":"The Naked Eye of {fn}","se.hero.subtitle":"A wide-open iris in direct contact with the live field — the world through it sharper, faster, and more saturated than the world beside it. Nothing between. Nothing kept.","se.hero.tag":"extraverted sensing","se.lab.btn.blackout.label":"Lights Out","se.lab.btn.blackout.sub":"the field empties — nothing to perceive","se.lab.btn.flicker.label":"A Flicker in the Crowd","se.lab.btn.flicker.sub":"one element shifts for 300 ms","se.lab.btn.window.label":"A Closing Window","se.lab.btn.window.sub":"an opening appears — and starts shutting","se.lab.intensity.aria":"Stimulus field intensity, from empty room to street carnival","se.lab.intensity.heading":"Field Intensity","se.lab.intensity.max":"street carnival","se.lab.intensity.min":"empty room","se.lab.meter.pleasure":"Contact Pleasure","se.lab.meter.stress":"Stress","se.lab.narration.blackout":{figure:"The last thing seen dies as an afterimage; the small glint leaving it, labelled for Si, is the stratum its sibling would have kept.",mechanism:"The field is gone, and the eye starts paying for silence — stress climbing on an empty room the way other functions pay for chaos. Se keeps nothing, so there is nothing to fall back on.",provenance:"currents"},"se.lab.narration.blackout2":{figure:"The meters snap home.",mechanism:"Contact restored — no residue, no backlog, no grudge. The blackout cost exactly what it lasted and nothing more. Functions that keep records recover slowly; the one that keeps nothing is also the one that resets instantly.",provenance:"currents"},"se.lab.narration.flicker":{figure:"Note the twin flicker outside the lens: same event, same size, gone unseen. That is the same world without Se pointed at it.",mechanism:"One element in the field shifted for three hundred milliseconds, and the lock landed before the thought did — a name for what moved arrives second.",provenance:"currents"},"se.lab.narration.flicker2":{figure:"The flicker is already gone from the chamber, and the eye is back to hunting.",mechanism:"Caught, tagged, released — nothing stored. What Se buys is not a memory of the change; it is the handful of milliseconds between the world moving and the body knowing.",provenance:"currents"},"se.lab.narration.flickerMiss":{figure:"The flicker ran its three hundred milliseconds and closed before the lock arrived.",mechanism:"Missed. The event was real and the perception honest — but from this deep in the stack, the signal reaches the eye after the moment has left. Too late to matter is a position cost, not a character flaw. Drag Se back up the rail in Zone B and try again.",provenance:"currents"},"se.lab.narration.hoverCoarse":"Your touch is now the most vivid object in the field, and the eye treats it accordingly: zero-lag tracking, tracers leaping at every quick move. You are experiencing the dominant preset — drop this glyph to Inferior in Zone B and the same touch becomes something the gaze trails behind, catches, and loses.","se.lab.narration.hoverFine":"The cursor is now the most vivid object in the field, and the eye treats it accordingly: zero-lag tracking, tracers leaping at every quick move. You are experiencing the dominant preset — drop this glyph to Inferior in Zone B and the same cursor becomes something the gaze trails behind, catches, and loses.","se.lab.narration.intro":"The field runs live: drifters, movers, the occasional flare — and the eye hunting through it, locking whatever moves. Slide the field intensity and watch stress and pleasure trade places, or spawn an event and watch the reticle answer.","se.lab.narration.introHintCoarse":"Press and drag in the chamber to become the target yourself.","se.lab.narration.introHintFine":"Hover the chamber to become the target yourself.","se.lab.narration.slider":{figure:"Drag the field from empty room to street carnival and watch the meters trade places — the render sharpens as the stream thickens.",mechanism:"More world produces more clarity: Se does not get overwhelmed by intensity, it gets focused. The emergency, for this function, is the other end of the slider.",provenance:"currents"},"se.lab.narration.window":{figure:"Watch the response streak against the shrinking gap.",mechanism:"An opening — and it is already closing. Perception here is not a report; it is a launch condition, and the answer leaves immediately.",provenance:"currents"},"se.lab.narration.windowHit":{figure:"One streak, one gap, daylight on both sides.",mechanism:"Threaded, with room to spare. The present offered a gap with a deadline, and seeing it and taking it were one motion. No deliberation appears anywhere in the loop — which is not recklessness; at this position, it is precision.",provenance:"currents"},"se.lab.narration.windowMiss":{figure:"The streak meets the closed edge.",mechanism:"Shut. The response fired exactly as designed — and arrived at a wall, because from this seat the signal spends hundreds of milliseconds in transit before the launch even begins. Select a higher slot in Zone B and spawn another window: position is the difference between an opening and a story about one.",provenance:"currents"},"se.lab.state.blackout":"Sensory Blackout","se.lab.state.equilibrium":"Open Field","se.lab.state.flow":"Full Contact","se.lab.state.hunger":"Stimulus Hunger","se.lab.state.late":"Out of Position","se.lab.telemetry.clarity":"Field clarity","se.lab.telemetry.cogState":"Cognitive state","se.lab.telemetry.crossHead":"cross-listen · the same events, arriving at Si","se.lab.telemetry.lock":"Time to lock","se.lab.telemetry.sibPleasure":"Si pleasure","se.lab.telemetry.sibStress":"Si stress","se.lab.telemetry.visitSi":"visit Si →","se.meta.title":"Se — Extraverted Sensing · CURRENTS","se.slot.auxiliary":{example:"An ISTP glances at the engine once and knows which of the four sounds does not belong.",figure:"The iris opens fully on cue and rests half-closed between.",mechanism:"In the second seat, the scene is read cleanly and then handed inward — to a framework or a value — before anything is done about it. Less appetite than a first seat, more selection: full attention for what the craft or the feeling currently cares about, polite idling through the rest.",provenance:"myers"},"se.slot.critical":{example:"An ESFJ relives the dropped tray for a week, frame by frame, without once being told how to carry two.",figure:"A replay reticle circling the missed frame.",mechanism:"In the sixth seat, the eye turns inward as a sergeant with perfect timing and no warmth: you did not see it, you were too slow, you looked ridiculous. Precise about the missed moment, useless about what to do with it, and aimed mostly at the self.",provenance:"beebe"},"se.slot.demon":{example:"At the end of a terrible month, an ENFP runs until their legs give out, on a road they never saw.",figure:"The iris jammed open, flooding on purpose.",mechanism:"The eighth seat runs rarest and crudest. When it erupts, sensation stops being perception and becomes something applied to the self — the punishing workout, the blackout night, the hand through the wall. It is the least practised seat in the stack, and by that point it is not seeing anything.",provenance:"beebe"},"se.slot.dominant":{example:"Mid-game, an ESTP is already moving when the lane opens; asked how they knew, they say they saw it.",figure:"CURRENTS draws this as a wide-open iris — the field crisp and saturated inside the ring, blurred outside it.",mechanism:"In the first seat, the world arrives at full resolution and zero delay: what moved, what changed, where the opening is — obvious, continuously, at no cost. Attention goes where the action is without being sent, and the body often answers before a plan exists. The price is retention: almost nothing is kept.",provenance:"myers"},"se.slot.inferior":{example:"An INFJ who forgets to eat all week orders everything on the menu at midnight, twice.",figure:"A pinhole that snaps to full aperture without warning.",mechanism:"In the fourth seat, the present is mostly static between insights: physical detail arrives late, partial, and slightly untrustworthy — where the keys are, what was just said, the state of the body. Under real stress the senses flood open all at once — Quenk's grip — with bingeing, recklessness, and a sudden appetite for intensity that does not sound like them.",provenance:"quenk"},"se.slot.opposing":{example:`An ISTJ who "doesn't notice décor" recites the room's four changes to win a point about the old sofa.`,figure:"Below the waterline, the iris flashes open once, pointedly.",mechanism:"The fifth seat opens the shadow — the four positions a person runs rarely, and mostly without noticing. Here contact wakes as contradiction: when the record says one thing and the room plainly shows another, a blunt, unusually vivid look at it, it is right there — held exactly long enough to defend the archive, then dropped.",provenance:"beebe"},"se.slot.tertiary":{example:"An ENTJ is fully in the body on Saturday's ride; by Monday the senses are back on summary.",figure:"A half-size iris on a timer.",mechanism:"In the third seat, presence comes in bursts, usually downstream of a plan: the dinner, the court, the stage get genuinely seen — then the long-range machinery resumes and the senses drop back to executive summary. It improves with age, mostly as permission: it turns out the world is allowed to be enjoyed directly.",provenance:"grant"},"se.slot.trickster":{example:"An INTP searches twenty minutes for the glasses on their own forehead, then swears the mug was never there.",figure:"The reticle locks, confidently, on empty space.",mechanism:"In the seventh seat, the present plays pranks: objects genuinely vanish and reappear, the obvious thing on the table goes unseen for ten minutes — and occasionally the reverse, total confident certainty about a physical detail that was never there. Neither state announces which one is running.",provenance:"beebe"},"se.zoneA.canvasAria":"Interactive visual representation of Extraverted Sensing as a wide-open iris-aperture: a live particle field runs blurred outside the ring and crisp, saturated, and trailed inside it, while a gaze reticle saccades to whatever moves and locks it within a frame. Move or drag the pointer to become the most vivid object in the field","se.zoneB.ageNote":"With age, lower stack positions gain fidelity, duty cycle, and a steadier gaze.","se.zoneB.heading":"The Eight Faces of Se","se.zoneB.lede":"The canvas draws Se as an eye in contact with a live field. Where Se sits in a person's stack — the fixed order their eight functions come in — decides how fast that contact is. Click a position to see the change, from the dominant's zero-lag lock to the trickster's confident sightings of things that were never there, and watch the catch rate decay down the stack. Drag the maturity slider to watch the lower seats steady with age.","se.zoneB.railAria":"Stack positions for Se","se.zoneC.heading":"What Feeds Into Se?","se.zoneC.lede":"Se gathers; it does not judge. Extraverted perception is fed by introverted judgment, so its real partners are Ti and Fi — the inner judges that tell the eye what matters. Click a feeder and watch salience reorganise.","se.zoneC.unstableDefault":"Unstable coupling: perception feeding perception, with nothing judging either.","se.zoneD.canvasAria":"The Se contact lab: a live stimulus field with an intensity slider, a saccading gaze that locks flickers, a closing window it fires a response through, and a blackout that starves it","se.zoneD.heading":"The Contact Lab","se.zoneD.kicker":"Zone D · the contact lab","se.zoneD.lede":"Se is a contact instrument: its quality is measured in milliseconds-to-lock and openings used, not in conclusions. This lab runs the eye against a live field you control. Slide the intensity from empty room to street carnival, spawn events, and note which end of the slider reads as the emergency.","se.zoneE.lede":"Patterns from the wild — how Se shows up in daily life."};N(F);function P(){const n={fn:s("--c-accent"),n:s("--c-n"),s:s("--c-s"),f:s("--c-f"),pos:[s("--pos-1"),s("--pos-2"),s("--pos-3"),s("--pos-4")],sh:s("--pos-sh"),warn:s("--warn"),crit:s("--crit"),ink:s("--ink"),ink2:s("--ink-2"),muted:s("--muted"),grid:s("--grid"),axis:s("--axis"),surface:s("--surface")},o=e=>({name:t(`site.position.${e}.name`),ord:t(`site.position.${e}.ord`)}),p=[{key:"dominant",...o("dominant"),types:"ESTP · ESFP",shadow:!1,series:0,params:{scale:1,fidelity:.95,latency:0,noise:0,duty:1,control:1,contrary:0},copy:a("se.slot.dominant")},{key:"auxiliary",...o("auxiliary"),types:"ISTP · ISFP",shadow:!1,series:1,params:{scale:.8,fidelity:.85,latency:80,noise:.05,duty:.85,control:.9,contrary:0},copy:a("se.slot.auxiliary")},{key:"tertiary",...o("tertiary"),types:"ENTJ · ENFJ",shadow:!1,series:2,params:{scale:.55,fidelity:.6,latency:250,noise:.2,duty:.5,control:.6,contrary:0},copy:a("se.slot.tertiary")},{key:"inferior",...o("inferior"),types:"INTJ · INFJ",shadow:!1,series:3,params:{scale:.4,fidelity:.35,latency:700,noise:.45,duty:.25,control:.35,contrary:.12},copy:a("se.slot.inferior")},{key:"opposing",...o("opposing"),types:"ISTJ · ISFJ",shadow:!0,series:4,params:{scale:.46,fidelity:.42,latency:600,noise:.5,duty:.45,control:.4,contrary:.25},copy:a("se.slot.opposing")},{key:"critical",...o("critical"),types:"ESTJ · ESFJ",shadow:!0,series:4,params:{scale:.44,fidelity:.35,latency:900,noise:.55,duty:.35,control:.3,contrary:.35},copy:a("se.slot.critical")},{key:"trickster",...o("trickster"),types:"INTP · INFP",shadow:!0,series:4,params:{scale:.42,fidelity:.28,latency:1200,noise:.6,duty:.3,control:.2,contrary:.55},copy:a("se.slot.trickster")},{key:"demon",...o("demon"),types:"ENTP · ENFP",shadow:!0,series:4,params:{scale:.4,fidelity:.2,latency:1500,noise:.65,duty:.22,control:.12,contrary:.65},copy:a("se.slot.demon")}],m={endurance:{w:.9,why:t("se.character.endurance.why")},precision:{w:.9,why:t("se.character.precision.why")},speed:{w:.97,why:t("se.character.speed.why")},control:{w:.85,why:t("se.character.control.why")},awareness:{w:.6,why:t("se.character.awareness.why")}},f=[{key:"ti",name:"Ti",color:"#4fc9e0",canonical:!0,cfg:{rate:.55,weight:1,speed:.8,spread:.3,focus:1,dwell:.5,aim:3.14},copy:a("se.feeder.ti")},{key:"fi",name:"Fi",color:"#f56a8c",canonical:!0,cfg:{rate:.6,weight:.9,speed:.7,spread:.5,focus:.8,dwell:1,aim:3},copy:a("se.feeder.fi")},{key:"ni",name:"Ni",color:n.n,canonical:!1,unstable:!0,cfg:{rate:.9,weight:.3,speed:.9,spread:1,focus:.3,dwell:.2,starve:!0},copy:a("se.feeder.ni")},{key:"fe",name:"Fe",color:"#f9748f",canonical:!1,cfg:{rate:.85,weight:.6,speed:.9,spread:.7,focus:.6,dwell:.15,sealed:!0,aim:3.05},copy:a("se.feeder.fe")},{key:"te",name:"Te",color:"#17d4ef",canonical:!1,cfg:{rate:.9,weight:.7,speed:.95,spread:.6,focus:.7,dwell:.1,sealed:!0,aim:3.2},copy:a("se.feeder.te")}];function g(e){const h=11.5*(e/60),l=e%8/8,c=1.5*Math.max(0,1-Math.abs(l-.1)*7);return Math.max(0,h-c)}function y(e){const h=19*Math.pow(e/60,1.22);let l=0;for(const[d,T]of[[11,10],[33,9],[58,12],[88,9]])e>=d&&(l+=T*u((e-d)/1.6,0,1));const c=e<2?0:1.7*Math.sin(e*.9)+1.3*Math.sin(e*2.3+.5);return u(h+l+c,0,100)}const r=[{key:"dom",label:t("site.position.dominant.name"),color:n.pos[0],f:g},{key:"aux",label:t("site.position.auxiliary.name"),color:n.pos[1],f:e=>20*Math.pow(e/60,1.06)},{key:"tert",label:t("site.position.tertiary.name"),color:n.pos[2],f:e=>29*Math.pow(e/60,1.4)},{key:"inf",label:t("site.position.inferior.name"),color:n.pos[3],f:e=>Math.min(100,84*Math.pow(e/60,1.9))},{key:"sh",label:t("site.position.shadow.name"),color:n.sh,f:y}],w=60*Math.pow(100/84,1/1.9),b=[{label:t("site.position.dominant.name"),v:1,color:n.pos[0],series:0},{label:t("site.position.auxiliary.name"),v:1.5,color:n.pos[1],series:1},{label:t("site.position.tertiary.name"),v:2.5,color:n.pos[2],series:2},{label:t("site.position.inferior.name"),v:4,color:n.pos[3],series:3},{label:t("site.position.shadow.name"),v:4.5,color:n.sh,band:[3,6],series:4}],v=[{label:t("site.position.dominant.name"),color:n.pos[0],note:t("se.energy.recovery.dominant"),f:e=>e<=30?100-r[0].f(e):i(0)+(100-i(0))*(1-Math.exp(-(e-30)/6))},{label:t("site.position.auxiliary.name"),color:n.pos[1],note:t("se.energy.recovery.auxiliary"),f:e=>e<=30?100-r[1].f(e):i(1)+(100-i(1))*(1-Math.exp(-(e-30)/10))},{label:t("site.position.tertiary.name"),color:n.pos[2],note:t("se.energy.recovery.tertiary"),f:e=>e<=30?100-r[2].f(e):i(2)+(100-i(2))*(1-Math.exp(-(e-30)/17))},{label:t("site.position.inferior.name"),color:n.pos[3],note:t("se.energy.recovery.inferior"),f:e=>e<=30?100-r[3].f(e):e<60?i(3):i(3)+(100-i(3))*(1-Math.exp(-(e-60)/21))},{label:t("site.position.shadow.name"),color:n.sh,note:t("se.energy.recovery.shadow"),f:e=>e<=30?100-r[4].f(e):i(4)+(92-i(4))*(1-Math.exp(-(e-30)/26))}];function i(e){return 100-r[e].f(30)}const k={buttons:[{id:"btnFlicker",key:"flicker",color:n.fn,impact:{stress:0,pleasure:.16},followMs:4200},{id:"btnWindow",key:"window",color:"#4fc9e0",impact:{stress:.1,pleasure:.06},followMs:4200},{id:"btnBlackout",key:"blackout",color:n.crit,impact:{stress:.28,pleasure:-.3},followMs:6600}],states:{flow:{label:t("se.lab.state.flow"),color:"#17c964"},equilibrium:{label:t("se.lab.state.equilibrium"),color:n.fn},hunger:{label:t("se.lab.state.hunger"),color:n.warn},late:{label:t("se.lab.state.late"),color:n.warn},blackout:{label:t("se.lab.state.blackout"),color:n.crit}},sibling:{flicker:{stress:.1,pleasure:0},window:{stress:.16,pleasure:0},blackout:{stress:-.06,pleasure:.12}},narrations:{slider:a("se.lab.narration.slider"),flicker:a("se.lab.narration.flicker"),flicker2:a("se.lab.narration.flicker2"),flickerMiss:a("se.lab.narration.flickerMiss"),window:a("se.lab.narration.window"),windowHit:a("se.lab.narration.windowHit"),windowMiss:a("se.lab.narration.windowMiss"),blackout:a("se.lab.narration.blackout"),blackout2:a("se.lab.narration.blackout2"),hover:x?t("se.lab.narration.hoverCoarse"):t("se.lab.narration.hoverFine")}},S={mirror:{label:"Se",counterpart:"Si",counterpartColor:"var(--pos-3)",copy:a("se.fieldNotes.mirror")},vignettes:[a("se.fieldNotes.vignette.court"),a("se.fieldNotes.vignette.loop"),a("se.fieldNotes.vignette.grip"),a("se.fieldNotes.vignette.scheduledBody"),a("se.fieldNotes.vignette.reckless"),a("se.fieldNotes.vignette.mistakenForNe"),a("se.fieldNotes.vignette.fiveYearPlan")]};return{COL:n,SLOTS:p,CHARACTER:m,FEEDERS:f,SERIES:r,GRIP_T:w,COSTS:b,RECOVERY:v,LAB:k,ZONE_F:S}}export{P as l};
